<template><div class="workflow-page"><header class="page-head"><div><span class="eyebrow">烘烤端</span><h1>烘烤批次</h1><p>记录烤房阶段、温湿度和异常情况。</p></div><button class="primary" @click="showForm=!showForm">{{showForm?'收起':'新建批次'}}</button></header><form v-if="showForm" class="form-panel" @submit.prevent="create"><div class="form-grid"><label>烘烤批次号<input v-model="form.batch_no" placeholder="如 2026-C-001" required></label><label>采收批次<select v-model="form.harvest_batch_id" required><option value="">请选择</option><option v-for="b in harvests" :value="b.id" :key="b.id">{{b.batch_no}} · {{b.fresh_weight}} kg</option></select></label><label>烤房<input v-model="form.barn_name" placeholder="1号烤房" required></label><label>当前阶段<select v-model="form.stage"><option value="yellowing">变黄</option><option value="color_fixing">定色</option><option value="stem_drying">干筋</option></select></label><label>温度（℃）<input v-model="form.temperature" type="number" step="0.1"></label><label>湿度（%）<input v-model="form.humidity" type="number" step="0.1"></label></div><button class="primary" :disabled="busy">{{busy?'保存中...':'保存批次'}}</button><p v-if="message" class="message">{{message}}</p></form><section class="table-panel"><div class="panel-title"><strong>烘烤记录</strong><span>{{items.length}} 条</span></div><div v-if="!items.length" class="empty">暂无烘烤批次。</div><div v-for="item in items" :key="item.id" class="batch-row"><div><strong>{{item.batch_no}}</strong><small>{{item.barn_name}} · {{stageText[item.stage]}} · {{item.temperature||'—'}}℃ / {{item.humidity||'—'}}%</small></div><span class="status">{{item.status}}</span></div></section></div></template>
<script>
import axios from 'axios'; import {API_BASE} from '@/config/api';
export default{data:()=>({harvests:[],items:[],showForm:false,busy:false,message:'',stageText:{yellowing:'变黄',color_fixing:'定色',stem_drying:'干筋',complete:'已完成'},form:{batch_no:'',harvest_batch_id:'',barn_name:'',stage:'yellowing',temperature:'',humidity:''}}),async mounted(){await Promise.all([this.loadHarvests(),this.load()]);},methods:{async loadHarvests(){const r=await axios.get(`${API_BASE}/harvest/batches/`);this.harvests=r.data.data?.items||[];},async load(){const r=await axios.get(`${API_BASE}/curing/batches/`);this.items=r.data.data?.items||[];},async create(){this.busy=true;try{await axios.post(`${API_BASE}/curing/batches/`,this.form);this.message='烘烤批次已保存';this.showForm=false;await this.load();}catch(e){this.message=e.response?.data?.msg||'保存失败';}finally{this.busy=false;}}}};
</script>
<style scoped>.workflow-page{max-width:1060px;margin:auto}.page-head{display:flex;justify-content:space-between;padding:18px 2px}.eyebrow{font-size:12px;color:#27865a;font-weight:700}.page-head h1{margin:6px 0;color:#1b583c;font-size:26px}.page-head p{margin:0;color:#789081;font-size:13px}.primary{border:0;background:#1f8758;color:#fff;border-radius:7px;padding:10px 15px}.form-panel,.table-panel{background:#fff;border:1px solid #dcebe1;border-radius:12px;padding:17px;margin-bottom:14px}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}label{display:block;color:#41634f;font-size:12px;font-weight:600;margin-bottom:13px}input,select{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:10px;border:1px solid #cfe2d5;border-radius:7px;font:inherit;font-weight:400}.panel-title{display:flex;justify-content:space-between;color:#285f43}.panel-title span,.batch-row small{color:#81988a;font-size:12px}.empty{text-align:center;padding:35px 5px;color:#82998d;font-size:13px}.batch-row{display:flex;justify-content:space-between;border-top:1px solid #edf3ee;padding:13px 0}.batch-row small{display:block;margin-top:4px}.status{padding:4px 8px;border-radius:20px;background:#e8f5ed;color:#278258;font-size:12px}.message{color:#2b8258;font-size:13px}@media(max-width:650px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:430px){.form-grid{grid-template-columns:1fr}}</style>
